const fs = require("fs");
const path = require("path");

const projectRoot = path.resolve(__dirname, "..");
const importPattern = /^\s*@import\s+url\((['"]?)([^)'"]+)\1\)\s*;\s*$/gm;
const urlPattern = /url\((['"]?)([^)'"]+)\1\)/g;

function rewriteUrls(css, sourcePath, outputPath) {
  return css.replace(urlPattern, (match, quote, value) => {
    if (/^(?:data:|https?:|\/|#)/i.test(value)) return match;

    const absoluteAssetPath = path.resolve(path.dirname(sourcePath), value);
    const relativeAssetPath = path
      .relative(path.dirname(outputPath), absoluteAssetPath)
      .split(path.sep)
      .join("/");

    return `url(${quote}${relativeAssetPath}${quote})`;
  });
}

function bundle(entryName, outputName) {
  const entryPath = path.join(projectRoot, `pages/${entryName}`);
  const outputPath = path.join(projectRoot, `pages/${outputName}`);
  const entryCss = fs.readFileSync(entryPath, "utf8");
  const bundledCss = entryCss.replace(
    importPattern,
    (statement, quote, importPath) => {
      const absoluteImportPath = path.resolve(path.dirname(entryPath), importPath);
      const importedCss = fs.readFileSync(absoluteImportPath, "utf8").trim();
      const projectPath = path.relative(projectRoot, absoluteImportPath);

      return `/* ${projectPath} */\n${rewriteUrls(importedCss, absoluteImportPath, outputPath)}`;
    },
  );

  fs.writeFileSync(
    outputPath,
    "/* Generated by: node scripts/bundle-css.js */\n" + bundledCss.trim() + "\n",
  );

  console.log(`Bundled CSS written to ${path.relative(projectRoot, outputPath)}`);
}

function inlineIndexCss() {
  const htmlPath = path.join(projectRoot, "index.html");
  const cssPath = path.join(projectRoot, "pages/index.css");
  const startMarker = "<!-- app-css:start -->";
  const endMarker = "<!-- app-css:end -->";
  const css = rewriteUrls(fs.readFileSync(cssPath, "utf8"), cssPath, htmlPath);
  const styleBlock = `${startMarker}\n    <style>\n${css}    </style>\n    ${endMarker}`;
  const html = fs.readFileSync(htmlPath, "utf8");
  const markedBlockPattern = /<!-- app-css:start -->[\s\S]*?<!-- app-css:end -->/;
  const initialBlockPattern = /    <style>[\s\S]*?<noscript><link rel="stylesheet" href="\.\/pages\/index\.css" \/><\/noscript>/;
  const pattern = markedBlockPattern.test(html)
    ? markedBlockPattern
    : initialBlockPattern;

  if (!pattern.test(html)) {
    throw new Error("Не найден блок CSS в index.html");
  }

  fs.writeFileSync(htmlPath, html.replace(pattern, styleBlock));
  console.log("Main CSS inlined into index.html");
}

bundle("index.source.css", "index.css");
bundle("404.source.css", "404.css");
inlineIndexCss();
